export const isExternalLink = (link) => {
    return (link.startsWith('http://') ||
        link.startsWith('https://') ||
        link.startsWith('#') ||
        link.startsWith('tel:') ||
        link.startsWith('mailto:') ||
        link.startsWith('app:'));
};
export const orderDayNames = (days) => {
    const lastElement = days.pop();
    days.unshift(lastElement);
    return days;
};
export const isImage = (url) => {
    const regx = /\.|\//gm;
    return regx.test(url);
};
export const getListingOnOneLine = (elements, template = '') => {
    let listingOnOneLine = '';
    elements.forEach((element, index) => {
        listingOnOneLine += `${!!template ? template.replaceAll('[__]', element) : element}`;
        listingOnOneLine +=
            index == elements.length - 2
                ? ' and '
                : elements.length > 1 && index < elements.length - 1
                    ? ', '
                    : '';
    });
    return listingOnOneLine;
};
export const buildErrorMessage = (inputs) => {
    let elements = '';
    elements = getListingOnOneLine(inputs);
    if (inputs.length) {
        return `"${elements}" input${inputs.length > 1 ? 's' : ''} ${inputs.length > 1 ? 'are' : 'is'}`;
    }
    return elements;
};
export const getPositionClass = (className, labelPosition) => {
    if (!!labelPosition)
        return `${className}-${labelPosition}`;
    return '';
};
export const getUUID = () => {
    return window.crypto.randomUUID();
};
export const isErrorMessageSet = (errorMessage) => {
    return !!errorMessage && typeof errorMessage !== 'string';
};
export const getCustomValidation = (customValidation, formControl) => {
    if (typeof customValidation === 'function') {
        const functionValidation = customValidation ?? ((_) => null);
        return functionValidation(formControl);
    }
    return null;
};
export const getCustomValidationMessage = (result, errorMessage) => {
    if (!!result && typeof result === 'object' && !!result['customValidation']) {
        const errorMessages = errorMessage;
        return isErrorMessageSet(errorMessage)
            ? errorMessages.customValidation || ''
            : '';
    }
    return '';
};
export const getMobileResolutionSize = (isMobile = true) => {
    if (isMobile)
        return '(max-width: 1000px)';
    return '(min-width: 1001px)';
};
